style:
.ecommerce-category-menu { position: relative; z-index: 40; border-top: 1px solid #eee; border-bottom: 1px solid #eee; background: #fff; }
.ecommerce-category-menu__inner { display: flex; align-items: center; justify-content: center; gap: 2rem; padding: .85rem 1.5rem; overflow-x: auto; }
.ecommerce-category-menu__item { position: relative; flex: 0 0 auto; }
.ecommerce-category-menu__link { display: flex; align-items: center; gap: .35rem; color: #252525; font-size: .95rem; text-decoration: none; white-space: nowrap; }
.ecommerce-category-menu__link:hover { color: #991b60; }
.ecommerce-category-menu__submenu { display: none; position: absolute; top: 100%; left: 0; min-width: 13rem; padding: .5rem; border: 1px solid #e5e7eb; border-radius: .65rem; background: #fff; box-shadow: 0 12px 30px rgba(0,0,0,.12); }
.ecommerce-category-menu__item:hover .ecommerce-category-menu__submenu,
.ecommerce-category-menu__item:focus-within .ecommerce-category-menu__submenu { display: grid; }
.ecommerce-category-menu__submenu a { padding: .65rem .8rem; border-radius: .45rem; color: #353535; text-decoration: none; white-space: nowrap; }
.ecommerce-category-menu__submenu a:hover { background: #f9eef5; color: #991b60; }
@media (max-width: 767px) { .ecommerce-category-menu__inner { justify-content: flex-start; gap: 1.25rem; } }
/* ecommerce-category-submenu-layer-fix */
@media (min-width: 768px) { .ecommerce-category-menu__inner { overflow: visible; } }
.ecommerce-category-menu__item { z-index: 41; }
.ecommerce-category-menu__submenu { z-index: 1000; }
